public async Task<IActionResult> Get(int id)
{
    var orders = await _orderService.SearchAsync(new OrderSearchRequest { PageSize = 1 });
    foreach (var order in orders)
    {
        if (order.OrderId == id)
        {
            return Ok(order);
        }
    }

    return NotFound();
}

public async Task<IActionResult> Cancel(int id, [FromBody] CancelRequest body)
{
    if (body == null || string.IsNullOrWhiteSpace(body.Reason))
    {
        return BadRequest("취소 사유가 필요합니다.");
    }

    try
    {
        await _orderService.CancelAsync(id, body.Reason);
        return NoContent();
    }
    catch (KeyNotFoundException)
    {
        return NotFound();
    }
    catch (InvalidOperationException ex)
    {
        return Conflict(ex.Message);
    }
}

public async Task<ActionResult<IReadOnlyList<Order>>> Search(
    [FromQuery] int? customerId,
    [FromQuery] OrderStatus? status,
    [FromQuery] DateTime? from,
    [FromQuery] DateTime? to,
    [FromQuery] string keyword,
    [FromQuery] int page = 1,
    [FromQuery] int pageSize = 20)
{
    var request = new OrderSearchRequest
    {
        CustomerId = customerId,
        Status = status,
        From = from,
        To = to,
        Keyword = keyword,
        Page = page,
        PageSize = pageSize
    };

    var orders = await _orderService.SearchAsync(request);
    return Ok(orders);
}

        public bool Run(DateTime businessDate)
        {
            var from = businessDate.Date;
            var to = from.AddDays(1);
            _log.WriteLine("[정산] 시작: {0:yyyy-MM-dd}", from);

            using (var conn = new SqlConnection(_connectionString))
            {
                conn.Open();

                // 같은 날짜를 두 번 정산하지 않는다.
                var already = conn.ExecuteScalar<int>(
                    "SELECT COUNT(*) FROM dbo.Settlements WHERE BusinessDate = @BusinessDate",
                    new { BusinessDate = from });
                if (already > 0)
                {
                    _log.WriteLine("[정산] 이미 정산된 날짜입니다. 건너뜁니다.");
                    return true;
                }

                var rows = conn.Query<SettlementSource>(@"
SELECT o.OrderId, o.SellerId, o.TotalAmount, o.ShippingFee, o.DiscountAmount, s.CommissionRate
FROM dbo.Orders o
JOIN dbo.Sellers s ON s.SellerId = o.SellerId
WHERE o.Status = 3
  AND o.DeliveredAt >= @From AND o.DeliveredAt < @To",
                    new { From = from, To = to }).ToList();

                if (rows.Count == 0)
                {
                    _log.WriteLine("[정산] 대상 주문이 없습니다.");
                    return true;
                }

                // 판매자별로 금액을 모은다.
                var bySeller = new Dictionary<int, SellerTotal>();
                foreach (var row in rows)
                {
                    if (row.TotalAmount <= 0)
                    {
                        _log.WriteLine("[정산] 금액이 0 이하인 주문을 건너뜁니다. OrderId={0}", row.OrderId);
                        continue;
                    }

                    SellerTotal total;
                    if (!bySeller.TryGetValue(row.SellerId, out total))
                    {
                        total = new SellerTotal { SellerId = row.SellerId };
                        bySeller.Add(row.SellerId, total);
                    }

                    var rate = row.CommissionRate.HasValue ? row.CommissionRate.Value : DefaultCommissionRate;
                    var sales = row.TotalAmount - row.ShippingFee;
                    var commission = Math.Round(sales * rate, 0, MidpointRounding.AwayFromZero);

                    total.OrderCount++;
                    total.SalesAmount += sales;
                    total.ShippingAmount += row.ShippingFee;
                    total.CommissionAmount += commission;
                    total.DiscountAmount += row.DiscountAmount;
                }

                var payouts = new List<SellerTotal>();
                var deferred = new List<SellerTotal>();
                foreach (var total in bySeller.Values.OrderBy(t => t.SellerId))
                {
                    total.PayoutAmount = total.SalesAmount + total.ShippingAmount - total.CommissionAmount;

                    // 최소 지급액 미만은 다음 정산으로 넘긴다.
                    if (total.PayoutAmount < MinimumPayout)
                    {
                        deferred.Add(total);
                        continue;
                    }

                    payouts.Add(total);
                }

                using (var tx = conn.BeginTransaction(IsolationLevel.ReadCommitted))
                {
                    try
                    {
                        foreach (var p in payouts)
                        {
                            conn.Execute(@"
INSERT INTO dbo.Settlements (BusinessDate, SellerId, OrderCount, SalesAmount, ShippingAmount, CommissionAmount, PayoutAmount, CreatedAt)
VALUES (@BusinessDate, @SellerId, @OrderCount, @SalesAmount, @ShippingAmount, @CommissionAmount, @PayoutAmount, SYSDATETIME())",
                                new
                                {
                                    BusinessDate = from,
                                    p.SellerId,
                                    p.OrderCount,
                                    p.SalesAmount,
                                    p.ShippingAmount,
                                    p.CommissionAmount,
                                    p.PayoutAmount
                                },
                                tx);
                        }

                        foreach (var d in deferred)
                        {
                            conn.Execute(
                                "INSERT INTO dbo.SettlementDeferrals (BusinessDate, SellerId, Amount) VALUES (@BusinessDate, @SellerId, @Amount)",
                                new { BusinessDate = from, d.SellerId, Amount = d.PayoutAmount },
                                tx);
                        }

                        tx.Commit();
                    }
                    catch (Exception ex)
                    {
                        tx.Rollback();
                        _log.WriteLine("[정산] 실패하여 롤백했습니다: {0}", ex.Message);
                        return false;
                    }
                }

                _log.WriteLine(
                    "[정산] 완료: 판매자 {0}명 지급, {1}명 이월, 총 지급액 {2:N0}원",
                    payouts.Count,
                    deferred.Count,
                    payouts.Sum(p => p.PayoutAmount));
                return true;
            }
        }

public OrderService(IOrderDao orderDao)
{
    if (orderDao == null)
    {
        throw new ArgumentNullException("orderDao");
    }

    _orderDao = orderDao;
}

public void Cancel(int orderId, string reason)
{
    if (orderId <= 0)
    {
        throw new ArgumentOutOfRangeException("orderId", "주문 번호가 올바르지 않습니다.");
    }

    if (string.IsNullOrWhiteSpace(reason))
    {
        throw new ArgumentException("취소 사유를 입력하세요.", "reason");
    }

    // 사유 정리: 앞뒤 공백 제거, 길이 제한
    var trimmed = reason.Trim();
    if (trimmed.Length > MaxReasonLength)
    {
        trimmed = trimmed.Substring(0, MaxReasonLength);
    }

    // 운영 데이터에 테스트 사유가 남지 않도록 막는다.
    foreach (var word in BlockedWords)
    {
        if (trimmed.Equals(word, StringComparison.OrdinalIgnoreCase))
        {
            throw new ArgumentException("사용할 수 없는 취소 사유입니다.", "reason");
        }
    }

    var order = _orderDao.GetOrder(orderId);
    if (order == null)
    {
        throw new KeyNotFoundException("주문을 찾을 수 없습니다. OrderId=" + orderId);
    }

    if (order.Status == OrderStatus.Cancelled)
    {
        // 이미 취소된 주문은 무시
        Trace.TraceInformation("이미 취소된 주문: {0}", orderId);
        return;
    }

    if (order.Status == OrderStatus.Delivered)
    {
        throw new InvalidOperationException("배송 완료된 주문은 취소할 수 없습니다.");
    }

    var previous = order.Status;
    var updated = _orderDao.UpdateStatus(orderId, OrderStatus.Cancelled, trimmed);
    if (updated != 1)
    {
        throw new InvalidOperationException("주문 상태를 변경하지 못했습니다. OrderId=" + orderId);
    }

    _orderDao.AddHistory(orderId, string.Format("주문 취소 ({0} -> Cancelled): {1}", previous, trimmed));

    if (previous == OrderStatus.Paid || previous == OrderStatus.Shipped)
    {
        // 환불은 정산 배치에서 처리한다.
        _orderDao.AddHistory(orderId, "환불 대기 등록");
    }

    Trace.TraceInformation("주문 취소 완료: {0}, 이전 상태 {1}", orderId, previous);
}

public OrderDao(string connectionString)
{
    if (string.IsNullOrEmpty(connectionString))
    {
        throw new ArgumentNullException("connectionString");
    }

    _connectionString = connectionString;
}

public OrderDto GetOrder(int orderId)
{
    using (IDbConnection conn = new SqlConnection(_connectionString))
    {
        return conn.Query<OrderDto>(
            @"SELECT o.OrderId, o.CustomerId, c.Name AS CustomerName, o.Status, o.TotalAmount, o.ShippingFee,
                     o.OrderedAt, o.PaidAt, o.ShippedAt, o.CancelledAt, o.CancelReason
              FROM dbo.Orders o
              JOIN dbo.Customers c ON c.CustomerId = o.CustomerId
              WHERE o.OrderId = @OrderId",
            new { OrderId = orderId }).FirstOrDefault();
    }
}

public IList<OrderDto> SearchOrders(int? customerId, OrderStatus? status, DateTime? from, DateTime? to, string keyword)
{
    var sql = new StringBuilder();
    sql.AppendLine("SELECT o.OrderId, o.CustomerId, c.Name AS CustomerName, o.Status, o.TotalAmount, o.ShippingFee, o.OrderedAt");
    sql.AppendLine("FROM dbo.Orders o");
    sql.AppendLine("JOIN dbo.Customers c ON c.CustomerId = o.CustomerId");
    sql.AppendLine("WHERE 1 = 1");

    var param = new DynamicParameters();

    if (customerId.HasValue)
    {
        sql.AppendLine("  AND o.CustomerId = @CustomerId");
        param.Add("CustomerId", customerId.Value);
    }

    if (status.HasValue)
    {
        sql.AppendLine("  AND o.Status = @Status");
        param.Add("Status", (int)status.Value);
    }

    if (from.HasValue)
    {
        sql.AppendLine("  AND o.OrderedAt >= @From");
        param.Add("From", from.Value);
    }

    if (to.HasValue)
    {
        sql.AppendLine("  AND o.OrderedAt < @To");
        param.Add("To", to.Value);
    }

    if (!string.IsNullOrEmpty(keyword))
    {
        // 고객 이름으로만 검색한다.
        sql.AppendLine("  AND c.Name LIKE @Keyword");
        param.Add("Keyword", "%" + keyword.Trim() + "%");
    }

    sql.AppendLine("ORDER BY o.OrderedAt DESC");

    using (IDbConnection conn = new SqlConnection(_connectionString))
    {
        return conn.Query<OrderDto>(sql.ToString(), param).ToList();
    }
}

public int UpdateStatus(int orderId, OrderStatus status, string reason)
{
    using (IDbConnection conn = new SqlConnection(_connectionString))
    {
        return conn.Execute(
            @"UPDATE dbo.Orders
              SET Status = @Status,
                  CancelledAt = CASE WHEN @Status = 9 THEN GETDATE() ELSE CancelledAt END,
                  CancelReason = CASE WHEN @Status = 9 THEN @Reason ELSE CancelReason END
              WHERE OrderId = @OrderId",
            new { OrderId = orderId, Status = (int)status, Reason = reason });
    }
}

